--
-- A tábla adatainak kiíratása `hir`
--

INSERT INTO `hir` (`id`, `cim`, `rovid_lerias`, `tartalom`, `datum`) VALUES
(1, 'MÉGIS KÉSZÜL A THE LAST OF US 3?', 'Úgy tűnik formálódik a The Last of Us 3, de még nagyon, de nagyon az elején tartanak a munkálatok.\r\n', 'Lehet imádni vagy utálni, de az biztos, hogy a The Last of Us Part I és II a modern játékvilág megkerülhetetlen alkotásai, amiknek folytatására milliók várnak. Akárcsak az HBO-féle TV-sorozat folytatására is. Utóbbi második szezonja, ha lassan is, de biztosan formálódik. Összeállt a stáb, megvannak a szereplők, még idén elkezdődnek a forgatások, jövőre pedig premiert kaphat az HBO The Last of Us sorozatának második szezonja.\n\nMI a helyzet a játékokkal?\nImmár biztos, hogy a Naughty Dog dolgozott egy spinoff játékon, egy multiplayerre fókuszáló The Last of Us epizódon, de ezt aztán törölték, sosem fog már elkészülni. Nem is baj, a legtöbben úgyis a sztorira kíváncsiak és a The Last of Us Part III-at várják már, ami úgy tűnik végre kezd formálódni. A Naughty Dog két napja tett közzé egy 2 órás videót a The Last of Us Part II készítéséről, ami már önmagában is izgalmas és neked is látnod kell, ha csíped a játékot. A vége pedig különösen érdekes, Neil Druckmann ugyanis személyesen mesél a széria jövőjéről. Elmondása szerint mindeddig koncepció szinten sem volt terve a folytatásra, így pedig nem akart belevágni semmibe. De - és ez egy nagy de - ez mostanság megváltozott!\n\nForrás: Esport 1', '2024-03-03'),
(3, 'Ingyenes a Ghostrunner', 'Április 11-én délután 5 órától kezdődően egészen április 18-ig 8000ft helyett most min minden PC-s játékos teljesen ingyen beszerezheti az Epic Games Store-ból', 'A Ghostrunner egy cyberpunk FPS játék, amiben keveredik a parkour és a közelharc, egy rendkívül pörgős köntösben és színes környezettel. Egyszerre találkozhatunk a Dredd bíró és a Mirror’s Edge jellegzetességeivel a játék során, és ha nagyon bejövős lenne az első rész, már kosárba is rakhatod a második részét.\r\n\r\nForrás: Leet.hu\r\n', '2024-04-11'),
(5, 'Kiderült mikor érkezik a Star Wars Outlaws és milyen ajándékok járnak az előrendeléshez', 'Hivatalos bejelentés előtt publikálták a legújabb Star Wars játék megjelenését', 'Úgy néz kis az Ubisoft nagy bejelentését mégsem sikerült titokban tartani, az Insider Gaming számolt be arról, hogy az Ubisoft Japan YouTube-csatornáján megjelent az előzetes leírása, ami szerint augusztus 30-án érkezik a Star Wars Outlaws, amely elérhető lesz PC-n, PlayStation 5-ön és Xbox konzolokon is. A megjelenés dátumán kívül arra is fény derült, hogy a klasszik kiadás mellett megjelenik majd egy Gold és egy Ultimate Edition is, ezekkel a felhasználó kap egy szezonbérletet, early access-t (jelen esetben 3 napot jelent a tényleges megjelenéshez képest) a játékhoz. A leírás értelmében azok, akik bizalmat szavaznak a Massive Entertainment új kalandjának, megkapják ajándékba a Kessel Runner Bonus Packet, ami kozmetikai finomságokkal dobja fel a Trailblazer űrhajót és speedert.\r\n\r\n', '2024-04-09'),
(6, 'Áremelés az EA-nél', 'Mostantól a standardért 2300, de a pro előfizetésért közel 7000 forintot kell fizetniük az előfizetőknek havi szinten', 'Az Electronic Arts kiadó 10 éve tartja fent előfizető szolgáltatását, aminek cserébe az előfizetők bizonyos EA játékokhoz kapnak hozzáférést, mind PC-n, PlayStation és Xbox konzolokon. A játékkiadó hirtelen jelentette be a díjainak emelését, sőt az újonnan regisztrálók már a megemelt árakat fizetik, míg az eddigi előfizetőknek csak májustól kell. Így néznek ki a frissített díjak:\r\n\r\nStandard: \r\n - havi: 4,99 -> 5,99 euró (kb. 2300) forint\r\n    - éves: 29,99 -> 39,99 euró (kb. 15.500) forint\r\n\r\nPro:\r\n    - havi: 14,99 -> 16,99 (kb. 6600) forint\r\n    - éves: 99,99 -> 119,99 euró (kb. 46.700) forint\r\n\r\nA kiadó hirtelen és magas emelést az infláció és a piaci értékek változásával indokolta – írja a GamesIndustry.biz\r\n', '2024-04-07');

