  `id` int(3) NOT NULL,
  `nev` varchar(255) NOT NULL,
  `fejleszto` varchar(255) NOT NULL,
  `kiado` varchar(255) NOT NULL,
  `mufaj` varchar(255) NOT NULL,
  `r_leiras` text NOT NULL,
  `h_lerias` text NOT NULL,
  `video_link` varchar(255) NOT NULL,
  `megjelenes_datum` varchar(255) NOT NULL,
  `ertekeles` float NOT NULL,
  `eredeti_ertekeles` float NOT NULL,
  `ar` int(3) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_hungarian_ci;

--
-- A tábla adatainak kiíratása `jatek`
--

INSERT INTO `jatek` (`id`, `nev`, `fejleszto`, `kiado`, `mufaj`, `r_leiras`, `h_lerias`, `video_link`, `megjelenes_datum`, `ertekeles`, `eredeti_ertekeles`, `ar`) VALUES
(1, 'The Last of Us: Part II.', 'Naughty Dog LLC, Iron Galaxy Studios', 'PlayStation PC LLC', 'Lövöldözős, Külső nézetes lövöldözős, Akció-kaland\r\n\r\n', 'Öt évvel azután, hogy veszélyes úton átkeltek a járvány sújtotta Egyesült Államokon, Ellie és Joel a wyomingi Jackson városában telepedett le. A túlélők virágzó közösségében élve békére és stabilitásra leltek, annak ellenére, hogy a fertőzöttek és más, kétségbeesett túlélők miatt folyamatos fenyegetésben éltek.\r\nMikor egy erőszakos esemény megzavarja a békét, Ellie kemény útra indul, hogy igazságot szolgáltasson és ismét békére leljen. Amint egyesével levadássza a felelősöket, szembe kell néznie tettei szörnyű fizikai és érzelmi következményeivel.', 'Éld át az egyre növekvő morális konfliktusokat, amelyeket Ellie kérlelhetetlen bosszúvágya korbácsol fel. A nyomában járó erőszak miatt megkérdőjelezed magadban a helyes és a helytelen fogalmát, a jó és a rossz harcát és a hős vagy gonosztevő megítélését.\r\n\r\nGyönyörű, de veszélyes világ:\r\nIndulj Ellie kalandjára, amely Jackson békés hegységei és erdőségeiből Seattle benőtt, burjánzó romjai közé vezet. Találkozz túlélők új csoportjaival, ismeretlen és veszélyes környezetben, és fedezd fel a fertőzöttek rémisztő fejlődését. A Naughty Dog legújabb motorja által életre keltett halálos karakterek és világ minden korábbinál valósághűbb és a legapróbb részletig kidolgozott.\r\n\r\nFeszült és kétségbeesett hangulatú túlélős akciójáték\r\nAz új, továbbfejlesztett játékrendszerek illenek Ellie útjának élet-halál kérdéseihez az ellenséges világban. Érezd át kétségbeesett küzdelmét a túlélésért a még jobb funkciók segítségével: nagy intenzitású közelharc, folyamatos mozgás és dinamikus lopakodás.\r\n\r\nFegyverek, tárgyak, képességek és frissítések széles választékával saját játékstílusodhoz igazíthatod Ellie tulajdonságait.', 'https://www.youtube.com/embed/vhII1qlcZ4E?si=XPplYVKBP1uUDnPG', '2020. június 19.\r\n\r\n', 6.4, 8.8, 30),
(2, 'F1 24', 'Codemasters', 'Electronic Arts, EA Sports', 'Versenyjáték, Sport-szimulációs videojáték, Stratégiai játék, Simulation Game, Racing, Sports', 'Legyél te az utolsó, aki fékez a kanyar előtt az EA SPORTS F1 24-ben, a 2024-es FIA Forma-1 Világbajnokság hivatalos videójátékában!\r\n\r\n', 'Az EA SPORTS F1 24 új lehetőségek egész sorát kínálja. Ilyen például az új, piros zászlós szabály – a versenyek baleset miatti megszakítása új stratégiai lehetőségeket rejt. A szintén most először használható 35%-os versenyhossz még több akciót és izgalmat kínál. A játékban természetesen megtalálható a teljes 2024-es szezon, mind a 20 versenyző és 10 csapat, valamint az idei évre ráncfelvarrott, minden korábbinál vadabb F1-es gépek.\r\n\r\nAlapítsd meg, és építsd fel az alapoktól az álomcsapatodat a My Team Career módban, versenyezz osztott képernyőn vagy a kibővített, platformok közötti játékot is támogató online multiplayerben, és vegyél részt vadonatúj RaceNet Ligákban, hogy ne csak a gépi ellenfeleket, hanem a világ legjobb játékosait is legyőzd.\r\n\r\nAz új F1 World módban kihívásokat teljesíthetsz, jutalmakért versenyezhetsz és egy új előrehaladási rendszerrel fejlesztheted autódat és versenyzői képességeidet. Az F1 24-ben tehát minden együtt van ahhoz, hogy egy teljes szezonra végtelen szórakozást nyújtson a Forma-1 szerelmeseinek!\r\n\r\n', 'https://www.youtube.com/embed/NnyCWsA6KSI?si=RocqQZGA_5Lk9vad', '2024. május 31.', 8, 8, 25),
(4, 'Rayman Legends', 'Ubisoft, Ubisoft Montpellier, Pastagames', 'Nintendo, Ubisoft', 'Platformjáték, Verekedős játék, Adventure', 'A Rayman® Franchise legújabb darabja, mely a sikeres \"Origins\" után újabb kalandokra hívja régebbi, de akár újabb játékosait, mindezt együtt, 4-fővel együtt játszva.', 'Michel Ancel, a Rayman®, a Beyond Good & Evil® és a Raving Rabbids® ünnepelt alkotója visszatér, hogy kibontakoztassa innovatív kreativitását a Rayman® franchise új belépésével.\r\n\r\nAmikor Rayman, Globox és a Teensies felfedeznek egy titokzatos sátrat, amely tele van lenyűgöző festményekkel, hirtelen egy sor mitikus új világba repülnek!\r\n\r\nCsatlakozz hozzájuk, ahogy futnak, ugrálnak és átcsapnak minden világon, hogy hazaérjenek, megmentsék a napot, és felfedezzék a legendás festmények titkait!', 'https://www.youtube.com/embed/yMIKs1PKrEM?si=pAKW7Girjb1tytFJ', '2013. augusztus 20.', 5.95, 8.9, 10),
(5, 'Rise of The Tomb Raider', 'Crystal Dynamics', 'Square Enix', 'Akció-kalandjáték, Puzzle játék, Third-person shooter, Lopakodós játék', 'A 2013-as Tomb Raider reboot folytatásaként a Rise of the Tomb Raider főszereplője ismét Lara Croft, akivel a világ több pontján is megfordulunk a változatos kalandjai során. Hősnőnknek igen nehéz megbirkóznia a múltbéli tetteivel, viszont ahhoz, hogy utazásának következő fejezetében is életben maradjon, meg kell tanulnia kamatoztatni a korábban szerzett képességeit és tudását, felül kell kerekednie érzésein. A Rise of the Tomb Raider tekintetében a fejlesztők ugyanakkora hangsúlyt fektettek a narratívára, mint az előző rész esetében, a páratlan látványért pedig a legújabb platformok hardverei felelnek.', 'A Rise of the Tomb Raider epikus, magas oktánszámú akciópillanatokat tartalmaz, amelyek a Föld legszebben ellenséges környezetében játszódnak, és egy filmszerű túlélési akciókalandot kínál, ahol csatlakozol Lara Crofthoz az első sírrabló expedícióján. Fedezze fel a félelmetes halálos sírokat – Hatalmas ősi terek tele vannak halálos csapdákkal, oldjon meg drámai környezeti rejtvényeket, és fejtse meg az ősi szövegeket, hogy felfedje a kriptákat, miközben egy felfedezésre váró titkokkal teli világba lép. Woman vs. Wild – Hódíts meg egy világot, amely hevesen védi titkait, viseld el a veszélyes körülményeket és az instabil tájakat, nézz szembe az ősi sírok őrzőiként szolgáló veszélyes vadon élő állatokkal, és fedezz fel hatalmas interaktív környezeteket. Guerrilla Combat – Használd a környezetet előnyödre, méretezd meg a fákat és merülj el a víz alatt, hogy elkerüld vagy legyőzd az ellenséget, állítsd be Lara felszerelését, fegyvereit és lőszereit játékstílusodnak megfelelően, készíts robbanóanyagokat menet közben, hogy káoszt szíts, és használd Lara jellegzetes harci íjait. és mászó fejszét.', 'https://www.youtube.com/embed/1_FIyNcQSgA?si=HvjQpM75vaxcFroX', '2016. február. 9', 9, 9, 25),
(6, 'Shadow of the Tomb Raider', 'Eidos-Montréal, Nixxes Software', 'Square Enix', 'Akció-kalandjáték, Puzzle játék, Lövöldözős játék', 'Fuss versenyt az idővel! Éld túl a veszélyes dzsungeleket és mentsd meg a világot! A maja apokalipszis közeleg, és ismét Lara feladata, hogy megakadályozza a végső pusztulást. Kisérd szemmel, ahogy a fiatal archeológusból igazi Tomb Raider válik!\r\n\r\nA nagysikerű trilógia harmadik részében Lara Latin-Amerikába látogat egy maja relikvia után kutatva, ami kapcsolatban állhat az apjával. De ahogy az lenni szokott, nem csak ő van a kincs nyomában. Vajon sikerül megelőznie vetélytársait?', 'Túlélni és boldogulni a Föld leghalálosabb helyén: A túlélés érdekében sajátíts el egy könyörtelen dzsungel környezetet. Fedezze fel a víz alatti környezetet, amely tele van hasadékokkal és mély alagútrendszerekkel.\r\n\r\nLégy eggyé a dzsungellel: Legyőzött és túlerőben van, Larának fel kell használnia a dzsungelt a javára. Hirtelen csapj le, és tűnj el, mint egy jaguár, használd a sarat álcázásként, és kelts félelmet az ellenségekben, hogy káoszt szíts.\r\n\r\nFedezze fel a sötét és brutális sírokat: A sírok rémisztőbbek, mint valaha, fejlett bejárási technikákat igényelnek, hogy elérjék őket, és ha bejutnak, tele vannak halálos rejtvényekkel.\r\n\r\nFedezze fel az Élő történelmet: Fedezzen fel egy rejtett várost, és fedezze fel a valaha talált legnagyobb központot a Tomb Raider játékban.', 'https://www.youtube.com/embed/XYtyeqVQnRI?si=K07uivcrLUegdEI0', '2018. szeptember 12.', 8.4, 8.8, 30),
(7, 'Grand Theft Auto V', 'Rockstar Games, Rockstar North', 'Rockstar Games', 'Akció-kalandjáték, Third-person shooter, Nonlinear gameplay', 'Amikor egy ifjú szélhámos, egy visszavonult bankrabló és egy brutális pszichopata szembetalálja magát az alvilág legijesztőbb, legtébolyultabb elemeivel, továbbá az amerikai kormánnyal és a szórakoztatóiparral, együtt kell végrehajtaniuk néhány veszedelmes rablást, hogy életben maradhassanak a kíméletlen városban, ahol nem bízhatnak senkiben – a legkevésbé egymásban.', 'A Grand Theft Auto V PC változata tartalmazza továbbá a Grand Theft Auto Online játékot, amelyben egyszerre 30 játékos és két néző élvezheti az akciót. Grand Theft Auto Online PC változata a konzolos verziók megjelenése óta kiadott összes játékmenet-frissítést és a Rockstar által létrehozott tartalmakat is magában foglalja, beleértve a balhékat és az ellenfélmódokat is.\r\n\r\nA Grand Theft Auto V és a Grand Theft Auto Online PC verziója a belső nézetű módot is tartalmazza, lehetővé téve a játékosok számára, hogy új módon fedezzék fel Los Santos és Blaine County bámulatosan részletgazdag világát.\r\n\r\nA Grand Theft Auto V PC verziója bevezeti továbbá a sokoldalú alkotóeszközökből álló Rockstar szerkesztőt, melynek segítségével gyorsan és egyszerűen rögzítheted, szerkesztheted és megoszthatod a Grand Theft Auto V és a Grand Theft Auto Online játékmenetének nagy pillanatait. A Rockstar szerkesztő rendezői módja lehetővé teszi, hogy egyedi jeleneteket tervezz a történetmód főszereplőivel, illetve gyalogosok és akár állatok részvételével – az elképzeléseid a szemed láttára válnak valóra! A különleges kameramanipulációs és szerkesztőeszközök (például a gyorsított és lassított felvétel), valamint a szűrők gazdag választéka mellett a játékosok az aláfestő zenét is összeállíthatják a GTAV rádióadók kínálatából, illetve dinamikusan alakíthatják az eredeti zenei anyag intenzitását. Az elkészült videókat közvetlenül a Rockstar szerkesztőből töltheted fel a YouTube és a Rockstar Games Social Club felületeire az egyszerű megosztás érdekében.\r\n\r\nA háttérzenék elismert alkotói, The Alchemist és Oh No a The Lab FM nevű új rádióadó műsorvezetőiként térnek vissza. A rádióadó a szerzőpáros új, exkluzív dalait sugározza majd, melyeket a játék eredeti zenei anyaga ihletett. A közreműködők névsorában olyan előadók szerepelnek, mint Earl Sweatshirt, Freddie Gibbs, Little Dragon, Killer Mike, Sam Herring ( Future Islands) és sokan mások. A játékosok mostantól a saját zenéiket hallgatva is barangolhatnak Los Santos és Blaine County útjain, hála a Self Radio nevű új rádióállomásnak, amely egyedi, felhasználók által összeállított zenei anyagot sugároz.', 'https://www.youtube.com/embed/QkkoHAzjnUs?si=7qMIfVTFZ1Eg3BPM', '2013. szeptember 17.', 8, 9.1, 20),
(8, 'The Sims 4', 'Maxis, The Sims Studio, Blind Squirrel Games', 'Electronic Arts', 'Életszimulációs játék, ingyenesen játszható, Alkalmi játék, Stratégiai játék, Simulation Game, Adventure', 'Engedd szabadjára a fantáziádat, és hozd létre a Simek egyedi világát, amely önmagad kifejezője. Töltsd le ingyen, és szabd testre minden részletet a simektől az otthonokig és még sok minden másig. Válaszd ki, hogyan néznek ki, hogyan viselkednek és öltözködnek a simek, majd döntsd el, hogyan élik meg mindennapjaikat. Tervezzen és építsen hihetetlen otthonokat minden család számára, majd díszítse kedvenc bútoraival és dekorációival. Utazz el különböző környékekre, ahol találkozhatsz más simekkel, és megismerheted az életüket. Fedezzen fel gyönyörű helyszíneket egyedi környezettel, és induljon spontán kalandokba. Kezeld a simek mindennapi életének hullámvölgyeit, és nézd meg, mi történik, ha saját valós életedből játszol ki forgatókönyveket. Mesélje el történeteit a maga módján, miközben kapcsolatokat épít, karriert és életre törekvő vágyait követi, és elmerül ebben a rendkívüli játékban, ahol a lehetőségek végtelenek.\r\n', 'Átesett a generációváltáson a még mindig rendkívüli népszerűségnek örvendő The Sims-sorozat is, így a műfajában egyedinek tekinthető élet-szimulátor keretein belül ezúttal minden eddiginél nagyobb szabadság, felejthetetlen élmények, valamint a virtuális világ szépségei várnak ránk.\r\n\r\nTermészetesen az alapokat tekintve mit sem változott a The Sims 4, így ezúttal is az lesz a feladatunk, hogy megalkossuk alteregónkat, felépítsük saját házunkat, kitűzzünk magunk elé egy teljesítendő életcélt, majd megpróbáljunk boldogulni a mindennapokban, miközben családot alapítunk, dolgozunk, szórakozni járunk, vagy csak egyszerűen élvezzük az életet.\r\n\r\nA The Sims 4-ben tehát lehetőségünk lesz valóra váltani minden olyan álmunkat, amire a való életben korántsem biztos, hogy képesek lennénk, mindezt pedig megerősíthetjük azzal, hogy a minden eddiginél komolyabb lehetőséget kínáló Create-A-Sim opcióban nem csak külsőleg, hanem belsőleg is megalkothatjuk virtuális másunkat.\r\n\r\nEz azonban még nem minden, hiszen a nagybetűs élet már nem lesz fenékig tejfel a The Sims 4-ben sem, a simek ugyanis olyan élethű érzelmekkel és változatos reakciókkal lettek gazdagabbak, hogy a játék által generált életszerű helyzeteket akár a valóságban is megtapasztalhatnánk. Ezen felül természetesen rengeteg új lehetőséggel kecsegtet számunkra a játék többi opciója is, így az új építkezési lehetőségnek köszönhetően már szinte csak pénztárcánk szabhat határt annak, hogy felépítsük álmaink otthonát.\r\n\r\nA Maxis természetesen gondoskodott arról, hogy a generációváltás a grafikában is megmutatkozzon, így nem csak óriási szabadság vár majd minket a The Sims 4 keretein belül, hanem rendkívül realisztikus és látványos küllem is, aminek köszönhetően minden eddiginél alaposabban beleélhetjük magunkat karakterünk virtuális életébe.', 'https://www.youtube.com/embed/WjPPjU8OARg?si=cWEeGpWbgpzbSLqe', '2014. szeptember 2.', 8, 8.7, 0),
(9, 'Stardew Valley', 'The Secret Police Limited, ConcernedApe LLC, ConcernedApe, Sickhead Games', 'Eric Barone, Chucklefish, Fangamer, ConcernedApe LLC, 505 Games', 'Indie játék, Szerepjáték, Kalandjáték, Életszimulációs játék', 'Örökölted nagyapád régi mezőgazdasági telkét a Stardew Valleyben. Kézzel lenyomható eszközökkel és néhány érmével felfegyverkezve elindulsz, hogy új életet kezdj. Meg lehet tanulni a földből élni, és virágzó otthonná varázsolni ezeket a benőtt mezőket? Nem lesz könnyű. Amióta a Joja Corporation a városba érkezett, a régi életmód teljesen eltűnt. A közösségi központ, amely egykor a város legélénkebb tevékenységi központja volt, mára romokban hever. De a völgy tele van lehetőségekkel. Egy kis odaadással lehet, hogy te leszel az, aki helyreállítja a Stardew Valley nagyszerűségét!\r\n', '8 játékos gazdálkodás! Hívj meg 1-7 játékost, hogy csatlakozzanak hozzád a völgyben online! A játékosok együtt dolgozhatnak egy virágzó farm felépítésében, megoszthatják az erőforrásokat, és javíthatják a helyi közösséget. Mivel több leosztás jobb, mint egy, a játékosoknak lehetőségük van az eladott termékek haszonkulcsának növelésére a nagyobb kihívást jelentő élmény érdekében.\r\n\r\nIdővel javítsa készségeit. Ahogy a küzdő zöldfülűből mestergazdává válsz, 5 különböző területen lépsz szintet: mezőgazdaság, bányászat, harc, halászat és takarmánykeresés. Ahogy haladsz, új főzési és kézműves recepteket tanulhatsz meg, új területeket nyithatsz meg felfedezésre, és testreszabhatod készségeidet a különféle szakmák közül választhat.\r\n\r\nLégy része a helyi közösségnek. Mivel több mint 30 egyedi karakter él a Stardew Valley-ben, nem lesz gondod új barátokat találni! Mindenkinek megvan a saját napi beosztása, születésnapja, egyedi mini jelenetei és új mondanivalója a hét és az év során. Ahogy barátkozik velük, megnyílnak feléd, segítséget kérnek személyes gondjaikhoz, vagy elmondják a titkaikat! Vegyen részt olyan szezonális fesztiválokon, mint a luau, a kísértetjárta labirintus és a téli csillag ünnepe.\r\n\r\nFedezzen fel egy hatalmas, titokzatos barlangot. Ahogy mélyebbre utazol a föld alatt, új és veszélyes szörnyekkel, erős fegyverekkel, új környezetekkel, értékes drágakövekkel, szerszámok készítéséhez és fejlesztéséhez szükséges nyersanyagokkal, valamint feltárandó rejtélyekkel találkozhatsz.\r\n\r\nLélegezzen új életet a völgybe. A JojaMart megnyitása óta a Stardew Valley régi életmódja megváltozott. A város infrastruktúrájának nagy része tönkrement. Segítsen visszaállítani Stardew Valley egykori dicsőségét a régi közösségi ház megjavításával, vagy válasszon egy másik utat, és egyesítse erőit a Joja Corporationnel.\r\n\r\nUdvaroljon, és vegyen feleségül egy partnert, akivel megoszthatja életét a farmon. 12 legény és legénynő áll rendelkezésére, amelyek mindegyike egyedi karakterfejlődési jelenetekkel rendelkezik. Miután megházasodott, partnere veled fog élni a farmon. Ki tudja, talán lesz gyereke és családot alapít?\r\n\r\nAdományozzon tárgyakat és ásványokat a helyi múzeumnak.\r\n\r\nFőzzön finom ételeket, és készítsen hasznos dolgokat, amelyek segítenek Önnek. A több mint 100 főzési és kézműves receptnek köszönhetően sokféle elkészíthető elem áll rendelkezésére. Egyes ételek, amelyeket készítesz, átmenetileg növelik a képességeidet, a futási sebességet vagy a harci képességeidet. Készítsen olyan hasznos tárgyakat, mint a madárijesztők, olajfőzők, kemencék, vagy akár a ritka és drága kristályárium.\r\n\r\nTedd testre karaktered és házad megjelenését. Több száz dekorációs elem közül választhat, így nem okoz gondot álmai otthonának megteremtése!', 'https://www.youtube.com/embed/ot7uXNQskhs?si=YCwqtKcNKZSI0c9I', '2016. február 26.', 8.5, 9, 15),
(10, 'Forza Horizon 5', 'Playground Games', 'Xbox Game Studios', 'Versenyjáték, Kalandjáték', 'Vár a tökéletes Horizon Kalandod! Száguldj Mexikó vibrálóan színes és folyamatosan változó nyitott tájain, határtalan, önfeledt vezetéssel a világ több száz legnagyszerűbb autójának volánja mögött.', 'Ez a saját Horizon Kalandod!\r\nSzáguldj lélegzetelállító kalandversenyeken Mexikó vibrálóan színes és folyamatosan változó nyitott tájain, határtalan, önfeledt vezetéssel a világ több száz legnagyszerűbb autójának volánja mögött.\r\n\r\nEgy változatos nyitott világ\r\nFedezd fel a megkapó ellentétek és szépség világát. Várnak az élettől pezsgő sivatagok, a buja dzsungelek, a történelmi városok, a rejtett romok, a kanyargó kanyonok és egy felhők közé törő, hófödte vulkán.\r\n\r\nEgy kalandokkal teli nyitott világ\r\nVesd bele magad a részletesen kidolgozott kampányba, amely több száz kihívással és örömteli tevékenységekért járó jutalmakkal vár. Találkozz új karakterekkel és légy részese történetük alakulásának a Horizon Történetek során.\r\n\r\nEgy folyamatosan változó nyitott világ\r\nMerülj el a lenyűgöző időjárási jelenségek sokszínűségében, amilyenek hatalmas porviharok vagy a heves trópusi égszakadások, ahogy Mexikó egyedülálló, dinamikusan változó évszakai hétről hétre új arcot kölcsönöznek a világnak. Térj vissza folyamatosan új eseményekért, kihívásokért, gyűjthető tárgyakért, jutalmaként és új felfedezhető helyszínekért. Sosem lesz két egyforma évszak.\r\n\r\nEgy közösségi nyitott világ\r\nCsatlakozz játékostársaidhoz, versengjetek együtt a Horizon Árkád szórakoztató, őrült kihívásaival, amelyekkel sosem ér véget az akció barátaiddal, menük, töltőképernyők és előszobák nélkül. Szerezz új barátokat a Horizon Open és a Horizon Túraversenyek során, és mutasd meg a világnak alkotásaidat a közösségi ajándékmegosztással.\r\n\r\nA saját nyitott világod\r\nHozd létre saját legszórakoztatóbb eseményeidet a nagy tudású EventLab játékfejlesztő eszközkészlettel, ahol egyedi versenyeket, kihívásokat, mutatványokat és akár teljesen saját játékmódokat is készíthetsz. Szabd testre autóidat még többféleképp, mint valaha, olyan új lehetőségekkel, mint a zárt és nyitott tetejű kabriók, a féknyergek egyedi festése és egyebek. Használd az új ajándékeső funkciót egyedi alkotásaid megosztására a közösséggel.\r\n\r\nVágj bele saját Horizon Kalandodba még ma!', 'https://www.youtube.com/embed/FYH9n37B7Yw?si=dz7_0Hyn-2wdyY5I', '2021. november 1.', 9.5, 9.2, 30);

